SET FOREIGN_KEY_CHECKS = 0;

-- ==========================================
-- 1. TẠO CẤU TRÚC BẢNG (SCHEMA)
-- ==========================================

-- Tạo bảng: classanimals (Các lớp động vật)
CREATE TABLE IF NOT EXISTS `classanimals` (
  `id_class` INT AUTO_INCREMENT PRIMARY KEY,
  `background_video` VARCHAR(255) NULL,
  `info` TEXT NULL,
  `name` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tạo bảng: animals (Danh sách các loài động vật)
CREATE TABLE IF NOT EXISTS `animals` (
  `id_animal` INT AUTO_INCREMENT PRIMARY KEY,
  `avatar` VARCHAR(255) NULL,
  `gioi_thieu_text` TEXT NULL,
  `imgqr3d` VARCHAR(255) NULL,
  `ngoai_hinh_text` TEXT NULL,
  `noi_sinh_song_image` VARCHAR(255) NULL,
  `noi_sinh_song_text` TEXT NULL,
  `name` VARCHAR(255) NOT NULL,
  `classanimals_id` INT NOT NULL,
  CONSTRAINT `fk_animals_class` FOREIGN KEY (`classanimals_id`) REFERENCES `classanimals` (`id_class`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tạo bảng: listanimals (Hình ảnh chi tiết các loài)
CREATE TABLE IF NOT EXISTS `listanimals` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `animalimage` VARCHAR(255) NULL,
  `animals_id` INT NOT NULL,
  CONSTRAINT `fk_listanimals_animals` FOREIGN KEY (`animals_id`) REFERENCES `animals` (`id_animal`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tạo bảng: user (Thành viên)
CREATE TABLE IF NOT EXISTS `user` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `email` VARCHAR(255) NULL,
  `password` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(50) NULL,
  `provider` VARCHAR(255) NULL,
  `username` VARCHAR(255) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tạo bảng: role (Vai trò hệ thống)
CREATE TABLE IF NOT EXISTS `role` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `description` TEXT NULL,
  `name` VARCHAR(255) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tạo bảng: user_role (Liên kết thành viên và vai trò)
CREATE TABLE IF NOT EXISTS `user_role` (
  `user_id` INT NOT NULL,
  `role_id` INT NOT NULL,
  PRIMARY KEY (`user_id`, `role_id`),
  CONSTRAINT `fk_user_role_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_user_role_role` FOREIGN KEY (`role_id`) REFERENCES `role` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tạo bảng: posts (Bài viết diễn đàn)
CREATE TABLE IF NOT EXISTS `posts` (
  `id_post` INT AUTO_INCREMENT PRIMARY KEY,
  `date` DATETIME NOT NULL,
  `image` VARCHAR(255) NULL,
  `title` VARCHAR(255) NOT NULL,
  `user_id` INT NOT NULL,
  CONSTRAINT `fk_posts_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tạo bảng: comments (Bình luận bài viết)
CREATE TABLE IF NOT EXISTS `comments` (
  `id_cmt` INT AUTO_INCREMENT PRIMARY KEY,
  `chat_data` TEXT NOT NULL,
  `date_time` DATETIME NOT NULL,
  `post_id` INT NOT NULL,
  `user_id` INT NOT NULL,
  CONSTRAINT `fk_comments_posts` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id_post`) ON DELETE CASCADE,
  CONSTRAINT `fk_comments_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tạo bảng: notifications (Log thông báo admin)
CREATE TABLE IF NOT EXISTS `notifications` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `type` VARCHAR(50) NOT NULL,
  `action` VARCHAR(100) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `message` TEXT NULL,
  `link` VARCHAR(255) NULL,
  `target_type` VARCHAR(50) NULL,
  `target_id` VARCHAR(50) NULL,
  `actor_id` INT NULL,
  `actor_name` VARCHAR(255) NULL,
  `actor_roles` VARCHAR(255) NULL,
  `meta_json` LONGTEXT NULL,
  `is_read` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_notifications_created_at` (`created_at`),
  INDEX `idx_notifications_is_read` (`is_read`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

